<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$msg='';$uploadDir=dirname(__DIR__).'/uploads';if(!is_dir($uploadDir))@mkdir($uploadDir,0755,true);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='delete'){$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT * FROM media WHERE id=?');$st->execute([$id]);if($m=$st->fetch()){$full=dirname(__DIR__).'/'.ltrim($m['path'],'/');if(is_file($full))@unlink($full);$pdo->prepare('DELETE FROM media WHERE id=?')->execute([$id]);}$msg='Media deleted.';}elseif(!empty($_FILES['file']['tmp_name'])){$f=$_FILES['file'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>8*1024*1024){$msg='Upload failed or file is larger than 8MB.';}else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/avif'=>'avif'];if(!isset($allowed[$mime])){$msg='Only JPG, PNG, WebP and AVIF images are allowed.';}else{$img=@getimagesize($f['tmp_name']);if(!$img){$msg='Invalid image.';}else{$base=preg_replace('/[^a-z0-9-]+/','-',strtolower(pathinfo($f['name'],PATHINFO_FILENAME)));$name=trim($base,'-').'-'.bin2hex(random_bytes(4)).'.'.$allowed[$mime];$dest=$uploadDir.'/'.$name;if(move_uploaded_file($f['tmp_name'],$dest)){$path='/uploads/'.$name;$st=$pdo->prepare('INSERT INTO media(file_name,path,mime_type,alt_text,width,height,file_size,created_at) VALUES(?,?,?,?,?,?,?,NOW())');$st->execute([$name,$path,$mime,trim($_POST['alt_text']??''),(int)$img[0],(int)$img[1],(int)$f['size']]);$msg='Media uploaded.';}}}}}}
$list=$pdo->query('SELECT * FROM media ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>Media Library</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">CMS</span><h1>Media Library</h1></div><a class="btn light" href="/admin/">Dashboard</a></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><form class="contact-form" method="post" enctype="multipart/form-data" style="max-width:700px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/avif" required><input name="alt_text" placeholder="Descriptive ALT text" required><button class="btn gold">Upload Image</button></form><div class="cards compact" style="margin-top:45px"><?php foreach($list as $m):?><article class="trip-card"><img src="<?=e($m['path'])?>" alt="<?=e($m['alt_text'])?>" style="width:100%;height:210px;object-fit:cover"><div class="trip-body"><h3><?=e($m['file_name'])?></h3><p><?=e($m['width'])?>×<?=e($m['height'])?> · <?=round($m['file_size']/1024)?> KB</p><p><code><?=e($m['path'])?></code></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn" name="action" value="delete" onclick="return confirm('Delete this image?')">Delete</button></form></div></article><?php endforeach;?></div></main></body></html>
